from itertools import combinations

def bg_color(grid):
    from collections import Counter
    c = Counter(v for row in grid for v in row)
    return c.most_common(1)[0][0]

def cells_of(grid, color):
    return [(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if v==color]

def max_bipartite_matching(edges_r, nR, nC):
    matchR = {}
    def try_k(r, seen):
        for c in edges_r[r]:
            if c in seen: continue
            seen.add(c)
            if c not in matchR or try_k(matchR[c], seen):
                matchR[c] = r; return True
        return False
    m = 0
    for r in range(nR):
        if try_k(r, set()): m += 1
    return m, matchR

def line_cover(grid, minority):
    """Rows and columns forming a minimum vertex cover of the minority cells (prefer more rows)."""
    nR, nC = len(grid), len(grid[0])
    cs = cells_of(grid, minority)
    edges_r = {r: sorted({j for (i,j) in cs if i==r}) for r in range(nR)}
    m, _ = max_bipartite_matching(edges_r, nR, nC)
    for k in range(0, nC+1):
        best = None
        for C in combinations(range(nC), k):
            Cs = set(C)
            R = {i for (i,j) in cs if j not in Cs}
            if k + len(R) == m:
                if best is None or len(R) > len(best[1]):
                    best = (Cs, R)
        if best: return best[1], best[0]
    return set(), set()

def complete_lines(grid, new=2):
    """Complete dashed minority-color lattice lines: background cells on each cover line become new."""
    bg = bg_color(grid)
    minority = next(v for v in {v for row in grid for v in row} if v != bg)
    rows, cols = line_cover(grid, minority)
    out = [row[:] for row in grid]
    for r in rows:
        js = [j for (i,j) in cells_of(grid, minority) if i==r]
        for j in range(min(js), max(js)+1):
            if out[r][j] == bg: out[r][j] = new
    for c in cols:
        is_ = [i for (i,j) in cells_of(grid, minority) if j==c]
        for i in range(min(is_), max(is_)+1):
            if out[i][c] == bg: out[i][c] = new
    return out

