lib = '''"""Reusable grid functions for ARC-style tasks."""

from collections import Counter
from itertools import combinations


def colors(grid):
    """The distinct colors present in the grid."""
    return {v for row in grid for v in row}


def bg_color(grid):
    """The most common color in the grid (the background)."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def minority_color(grid):
    """The least common non-background color... the single non-background color if there is one."""
    bg = bg_color(grid)
    return next(v for v in colors(grid) if v != bg)


def cells_of(grid, color):
    """The positions (row, col) of every cell of the given color."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color]


def _max_matching(edges_r, nR, nC):
    """Maximum bipartite matching between nR left nodes and nC right nodes."""
    matchR = {}
    def try_k(r, seen):
        for c in edges_r[r]:
            if c in seen:
                continue
            seen.add(c)
            if c not in matchR or try_k(matchR[c], seen):
                matchR[c] = r
                return True
        return False
    m = 0
    for r in range(nR):
        if try_k(r, set()):
            m += 1
    return m


def line_cover(grid, color=None):
    """A minimum set of rows and columns covering all cells of color (rows preferred on ties)."""
    if color is None:
        color = minority_color(grid)
    nR, nC = len(grid), len(grid[0])
    cs = cells_of(grid, color)
    edges_r = {r: sorted({j for (i, j) in cs if i == r}) for r in range(nR)}
    m = _max_matching(edges_r, nR, nC)
    for k in range(nC + 1):
        best = None
        for C in combinations(range(nC), k):
            Csv = set(C)
            R = {i for (i, j) in cs if j not in Csv}
            if k + len(R) == m and (best is None or len(R) > len(best[1])):
                best = (Csv, R)
        if best:
            return best[1], best[0]
    return set(), set()


def complete_lines(grid, new=2, color=None):
    """Complete dashed lattice lines of the minority color: background cells on each cover line,
    between the extreme crossing lines, become new."""
    bg = bg_color(grid)
    if color is None:
        color = minority_color(grid)
